    except Exception as e:
        error_type = type(e).__name__
        root_cause = rule_library.match(error_type)
        if root_cause:
            fix = root_cause.get_fix()
            if fix and safe_to_apply(fix):
                fix.apply()
                return agent.execute()
        notify_human(agent, e)
        return None
    return result

