import sys, os, subprocess, traceback, json, logging
from typing import Dict, Callable, Any

class IntrospectionDebugger:
    def __init__(self, rule_lib: Dict[str, Callable] = None, logger=None):
        self.rule_lib = rule_lib or {}
        self.logger = logger or logging.getLogger('debugger')
        self.telemetry = []

    def capture_exception(self, exc: Exception, context: Dict[str, Any]) -> None:
        exc_type = type(exc).__name__
        self.logger.error(f'Captured {exc_type}: {exc}')
        self.telemetry.append({'type': exc_type, 'context': context, 'trace': traceback.format_exc()})
        root_cause = self.analyze_root_cause(exc_type, context)
        if root_cause:
            self.auto_repair(root_cause)

    def analyze_root_cause(self, exc_type: str, context: Dict[str, Any]) -> str:
        for pattern, fix in self.rule_lib.items():
            if pattern in exc_type.lower():
                return fix
        return None

    def auto_repair(self, fix: Callable) -> None:
        try:
            fix()
            self.logger.info('Automatic repair succeeded')
        except Exception as e:
            self.logger.warning(f'Repair failed: {e}')
            self.notify_human({'error': str(e)})

    def notify_human(self, payload: Dict) -> None:
        print('Human notification:', json.dumps(payload))
